 function mesh(geo,color,g,pos=[0,0,0]){const o=new T.Mesh(geo,new T.MeshStandardMaterial({color:colors[color]??color,metalness:.35,roughness:.5}));o.position.set(...pos);g.add(o);o.userData.part=Object.keys(groups).find(k=>groups[k]===g);pick.push(o);return o;}
 const box=(size,p,color,g)=>mesh(new T.BoxGeometry(...size),color,g,p);
 function tube(a,b,r,color,g){const av=new T.Vector3(...a),bv=new T.Vector3(...b),o=mesh(new T.CylinderGeometry(r,r,av.distanceTo(bv),12),color,g);o.position.copy(av.add(bv).multiplyScalar(.5));o.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),new T.Vector3(...b).sub(new T.Vector3(...a)).normalize());return o;}
 function disc(r,h,pos,color,g){const o=mesh(new T.CylinderGeometry(r,r,h,40),color,g,pos);o.rotation.x=Math.PI/2;return o;}
